        questText2.text = _currentQuest.QuestDescription;
        questText.fontStyle = FontStyles.Strikethrough;   // the finished quest, struck out
    }
}

// CustomerList.cpp: a hand-written doubly linked list.
// Insert a customer so the queue stays sorted by the service they need.
Node* customerList::insertSorted(Node* sortedHead, Node* newNode)
{
    if (sortedHead == nullptr || newNode->data.actionType < sortedHead->data.actionType)
    {
        newNode->next = sortedHead;
        if (sortedHead != nullptr) sortedHead->prev = newNode;
        return newNode;                            // new head
    }

    Node* current = sortedHead;
    while (current->next != nullptr && current->next->data.actionType <= newNode->data.actionType)
        current = current->next;

    newNode->next = current->next;
    if (current->next != nullptr) current->next->prev = newNode;
    current->next = newNode;
    newNode->prev = current;
    return sortedHead;
}

// Customer.cpp: elderly customers get their own numbering (E1, E2...),
// everyone else is numbered after them (Y1, Y2...)
void Customer::setAppointmentNumber(int customersInQueue, int elderCustomersInQueue)
{
    if (customersInQueue == elderCustomersInQueue || customersInQueue == 0) customersInQueue++;
    if (isElderly()) appointmentNumber = "E" + to_string(elderCustomersInQueue);
    else             appointmentNumber = "Y" + to_string(customersInQueue - elderCustomersInQueue);
}

